SECTOR_BY_ID = {s["id"]: s for s in SECTORS}


def sector_by_id(key):
    return SECTOR_BY_ID.get(key)


def related_company_codes(key):
    item = sector_by_id(key)
    return [code for code, _, _ in item["companies"]] if item else []


def relationship_index():
    index = {}
    for item in SECTORS:
        for code, role, confidence in item["companies"]:
            index.setdefault(code, []).append((item["title"], role, confidence))
    return index


def supply_chain_dot(sector):
    """Escaped three-node schematic; no dependency on a remote image service."""
    lines = ['digraph G {', 'rankdir=LR;', 'bgcolor="transparent";',
             'graph [pad="0.24", nodesep="0.32", ranksep="0.42"];',
             'node [shape=box, style="rounded,filled", color="#567dbb", fillcolor="#172b44", fontcolor="#e9f2ff", fontname="Arial", fontsize=12, margin="0.14,0.1"];',
             'edge [color="#63b3ed", penwidth=2.0, arrowsize=0.7];']
    for i, (stage, desc) in enumerate(sector["chain"]):
        label = stage + "\\n" + desc.replace("／", " / ")
        lines.append(f'n{i} [label={json.dumps(label, ensure_ascii=False)}];')
        if i:
            lines.append(f'n{i-1} -> n{i};')
    lines.append('}')
    return "\n".join(lines)
